import{_ as i,a0 as a,w as o,s as l,I as s,x as t,a1 as n,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups","title":"LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups.md","filePath":"[post].md"}'),m={name:"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups.md"};function g(u,e,c,v,A,b){const d=a("Link");return o(),l("div",null,[e[21]||(e[21]=s("h1",{id:"lfcs-系列第六讲-组装分区为raid设备——创建和管理系统备份",tabindex:"-1"},[t("LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份 "),s("a",{class:"header-anchor",href:"#lfcs-系列第六讲-组装分区为raid设备——创建和管理系统备份","aria-label":"Permalink to “LFCS 系列第六讲：组装分区为RAID设备——创建和管理系统备份”"},"​")],-1)),e[22]||(e[22]=s("p",null,"Linux 基金会已经发起了一个全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金会认证系统管理员）认证，旨在让来自世界各地的人有机会参加到 LFCS 测试，获得关于有能力在 Linux 系统中执行中级系统管理任务的认证。该认证包括：维护正在运行的系统和服务的能力、全面监控和分析的能力以及何时向上游团队请求支持的决策能力。",-1)),e[23]||(e[23]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-6.png",alt:"Linux Foundation Certified Sysadmin – Part 6"})],-1)),e[24]||(e[24]=s("p",null,[s("em",null,"LFCS 系列第六讲")],-1)),e[25]||(e[25]=s("p",null,"以下视频介绍了 Linux 基金会认证程序。",-1)),e[26]||(e[26]=s("p",null,"注：youtube 视频",-1)),e[27]||(e[27]=s("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),e[28]||(e[28]=s("p",null,"本讲是系列教程中的第六讲，在这一讲里，我们将会解释如何将分区组装为 RAID 设备——创建和管理系统备份。这些都是 LFCS 认证中的必备知识。",-1)),e[29]||(e[29]=s("h3",{id:"了解raid",tabindex:"-1"},[t("了解RAID "),s("a",{class:"header-anchor",href:"#了解raid","aria-label":"Permalink to “了解RAID”"},"​")],-1)),e[30]||(e[30]=s("p",null,"这种被称为独立磁盘冗余阵列（Redundant Array of Independent Disks）(RAID)的技术是将多个硬盘组合成一个单独逻辑单元的存储解决方案，它提供了数据冗余功能并且改善硬盘的读写操作性能。",-1)),e[31]||(e[31]=s("p",null,"然而，实际的容错和磁盘 I/O 性能硬盘取决于如何将多个硬盘组装成磁盘阵列。根据可用的设备和容错/性能的需求，RAID 被分为不同的级别，你可以参考 RAID 系列文章以获得每个 RAID 级别更详细的解释。",-1)),s("ul",null,[s("li",null,[n(d,{href:"https://linux.cn/article-6085-1.html"},{default:p(()=>[...e[0]||(e[0]=[t("在 Linux 下使用 RAID（一）：介绍 RAID 的级别和概念",-1)])]),_:1})])]),e[32]||(e[32]=r(`<p>我们选择用于创建、组装、管理、监视软件 RAID 的工具，叫做 mdadm (multiple disk admin 的简写）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- Debian 及衍生版 ----------------</span></span>
<span class="line"><span># aptitude update &amp;&amp; aptitude install mdadm</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- Red Hat 和基于 CentOS 的系统 ----------------</span></span>
<span class="line"><span># yum update &amp;&amp; yum install mdadm</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- openSUSE 上 ----------------</span></span>
<span class="line"><span># zypper refresh &amp;&amp; zypper install mdadm #</span></span></code></pre></div><h4 id="将分区组装成-raid-设备" tabindex="-1">将分区组装成 RAID 设备 <a class="header-anchor" href="#将分区组装成-raid-设备" aria-label="Permalink to “将分区组装成 RAID 设备”">​</a></h4><p>组装已有分区作为 RAID 设备的过程由以下步骤组成。</p><p><strong>1. 使用 mdadm 创建阵列</strong></p><p>如果先前其中一个分区已经格式化，或者作为了另一个 RAID 阵列的一部分，你会被提示以确认创建一个新的阵列。假设你已经采取了必要的预防措施以避免丢失重要数据，那么可以安全地输入 Y 并且按下回车。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mdadm --create --verbose /dev/md0 --level=stripe --raid-devices=2 /dev/sdb1 /dev/sdc1</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Creating-RAID-Array.png" alt="Creating RAID Array"></p><p><em>创建 RAID 阵列</em></p><p><strong>2. 检查阵列的创建状态</strong></p><p>在创建了 RAID 阵列之后，你可以检查使用以下命令检查阵列的状态。</p><pre><code># cat /proc/mdstat
or
# mdadm --detail /dev/md0    [More detailed summary]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Array-Status.png" alt="Check RAID Array Status"></p><p><em>检查 RAID 阵列的状态</em></p><p><strong>3. 格式化 RAID 设备</strong></p>`,17)),s("p",null,[e[2]||(e[2]=t("如本系列",-1)),n(d,{href:"https://linux.cn/article-7187-1.html"},{default:p(()=>[...e[1]||(e[1]=[t("第四讲",-1)])]),_:1}),e[3]||(e[3]=t("所介绍的，按照你的需求/要求采用某种文件系统格式化你的设备。",-1))]),e[33]||(e[33]=r(`<p><strong>4. 监控 RAID 阵列服务</strong></p><p>让监控服务时刻监视你的 RAID 阵列。把<code># mdadm --detail --scan</code>命令输出结果添加到 <code>/etc/mdadm/mdadm.conf</code>(Debian及其衍生版)或者<code>/etc/mdadm.conf</code>(Cent0S/openSUSE)，如下。</p><pre><code># mdadm --detail --scan
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Monitor-RAID-Array.png" alt="Monitor RAID Array"></p><p><em>监控 RAID 阵列</em></p><pre><code># mdadm --assemble --scan     [Assemble the array]
</code></pre><p>为了确保服务能够开机启动，需要以 root 权限运行以下命令。</p><p><strong>Debian 及其衍生版</strong></p><p>Debian 及其衍生版能够通过下面步骤使服务默认开机启动：</p><pre><code># update-rc.d mdadm defaults
</code></pre><p>在 <code>/etc/default/mdadm</code> 文件中添加下面这一行</p><pre><code>AUTOSTART=true
</code></pre><p><strong>CentOS 和 openSUSE(systemd-based)</strong></p><pre><code># systemctl start mdmonitor
# systemctl enable mdmonitor
</code></pre><p><strong>CentOS 和 openSUSE(SysVinit-based)</strong></p><pre><code># service mdmonitor start
# chkconfig mdmonitor on
</code></pre><p><strong>5. 检查RAID磁盘故障</strong></p><p>在支持冗余的的 RAID 级别中，在需要时会替换故障的驱动器。当磁盘阵列中的设备出现故障时，仅当存在我们第一次创建阵列时预留的备用设备时，磁盘阵列会将自动启动重建。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Faulty-Disk.png" alt="Check RAID Faulty Disk"></p><p><em>检查 RAID 故障磁盘</em></p><p>否则，我们需要手动将一个额外的物理驱动器插入到我们的系统，并且运行。</p><pre><code># mdadm /dev/md0 --add /dev/sdX1
</code></pre><p>/dev/md0 是出现了问题的阵列，而 /dev/sdx1 是新添加的设备。</p><p><strong>6. 拆解一个工作阵列</strong></p><p>如果你需要使用工作阵列的设备创建一个新的阵列，你可能不得不去拆解已有工作阵列——(可选步骤)</p><pre><code># mdadm --stop /dev/md0                 #  Stop the array
# mdadm --remove /dev/md0             # Remove the RAID device
# mdadm --zero-superblock /dev/sdX1     # Overwrite the existing md superblock with zeroes
</code></pre><p><strong>7. 设置邮件通知</strong></p><p>你可以配置一个用于发送通知的有效邮件地址或者系统账号(确保在 mdadm.conf 文件中有下面这一行)。——(可选步骤)</p><pre><code>MAILADDR root
</code></pre><p>在这种情况下，来自 RAID 后台监控程序所有的通知将会发送到你的本地 root 账号的邮件箱中。其中一个类似的通知如下。</p><p>说明：此次通知事件和第5步中的例子相关。此处一个设备被标志为错误，并且一个空闲的设备自动地被 mdadm 加入到阵列。我们用完了所有“健康的”空闲设备，因此我们得到了通知。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/RAID-Monitoring-Alerts.png" alt="RAID Monitoring Alerts"></p><p><em>RAID 监控通知</em></p><h4 id="了解-raid-级别" tabindex="-1">了解 RAID 级别 <a class="header-anchor" href="#了解-raid-级别" aria-label="Permalink to “了解 RAID 级别”">​</a></h4><p><strong>RAID 0</strong></p><p>阵列总大小是最小分区大小的 n 倍，n 是阵列中独立磁盘的个数(你至少需要两个驱动器/磁盘)。运行下面命令，使用 /dev/sdb1 和 /dev/sdc1 分区组装一个 RAID 0 阵列。</p><pre><code># mdadm --create --verbose /dev/md0 --level=stripe --raid-devices=2 /dev/sdb1 /dev/sdc1
</code></pre><p>常见用途：用于支持性能比容错更重要的实时应用程序的设置</p><p><strong>RAID 1 (又名镜像)</strong></p><p>阵列总大小等于最小分区大小(你至少需要两个驱动器/磁盘)。运行下面命令，使用 /dev/sdb1 和 /dev/sdc1 分区组装一个 RAID 1 阵列。</p><pre><code># mdadm --create --verbose /dev/md0 --level=1 --raid-devices=2 /dev/sdb1 /dev/sdc1
</code></pre><p>常见用途：操作系统的安装或者重要的子文件夹，例如 /home</p><p><strong>RAID 5 (又名奇偶校验码盘)</strong></p><p>阵列总大小将是最小分区大小的 (n-1) 倍。所减少的大小用于奇偶校验(冗余)计算(你至少需要3个驱动器/磁盘)。</p><p>说明：你可以指定一个空闲设备 (/dev/sde1) 替换问题出现时的故障部分(分区)。运行下面命令，使用 /dev/sdb1, /dev/sdc1, /dev/sdd1，/dev/sde1 组装一个 RAID 5 阵列，其中 /dev/sde1 作为空闲分区。</p><pre><code># mdadm --create --verbose /dev/md0 --level=5 --raid-devices=3 /dev/sdb1 /dev/sdc1 /dev/sdd1 --spare-devices=1 /dev/sde1
</code></pre><p>常见用途：Web 和文件服务</p><p><strong>RAID 6 (又名双重奇偶校验码盘)</strong></p><p>阵列总大小为(n<em>s)-2</em>s，其中n为阵列中独立磁盘的个数，s为最小磁盘大小。</p><p>说明：你可以指定一个空闲分区(在这个例子为 /dev/sdf1)替换问题出现时的故障部分(分区)。</p><p>运行下面命令，使用 /dev/sdb1, /dev/sdc1, /dev/sdd1, /dev/sde1 和 /dev/sdf1 组装 RAID 6 阵列，其中 /dev/sdf1 作为空闲分区。</p><pre><code># mdadm --create --verbose /dev/md0 --level=6 --raid-devices=4 /dev/sdb1 /dev/sdc1 /dev/sdd1 /dev/sde --spare-devices=1 /dev/sdf1
</code></pre><p>常见用途：大容量、高可用性要求的文件服务器和备份服务器。</p><p><strong>RAID 1+0 (又名镜像条带)</strong></p><p>因为 RAID 1+0 是 RAID 0 和 RAID 1 的组合，所以阵列总大小是基于两者的公式计算的。首先，计算每一个镜像的大小，然后再计算条带的大小。</p><pre><code># mdadm --create --verbose /dev/md0 --level=10 --raid-devices=4 /dev/sd[b-e]1 --spare-devices=1 /dev/sdf1
</code></pre><p>常见用途：需要快速 IO 操作的数据库和应用服务器</p><h4 id="创建和管理系统备份" tabindex="-1">创建和管理系统备份 <a class="header-anchor" href="#创建和管理系统备份" aria-label="Permalink to “创建和管理系统备份”">​</a></h4><p>记住， RAID 其所有的价值不是在于备份的替换者！在黑板上写上1000次，如果你需要的话，但无论何时一定要记住它。在我们开始前，我们必须注意的是，没有一个放之四海皆准的针对所有系统备份的解决方案，但这里有一些东西，是你在规划一个备份策略时需要考虑的。</p><ul><li>你的系统将用于什么？(桌面或者服务器？如果系统是应用于后者，那么最重要的服务是什么？哪个配置是痛点？)</li><li>你每隔多久备份你的系统？</li><li>你需要备份的数据是什么(比如文件/文件夹/数据库转储)？你还可以考虑是否需要备份大型文件(比如音频和视频文件)。</li><li>这些备份将会存储在哪里(物理位置和媒体)？</li></ul><p><strong>备份你的数据</strong></p><p>方法1：使用 dd 命令备份整个磁盘。你可以在任意时间点通过创建一个准确的镜像来备份一整个硬盘或者是分区。注意当设备是离线时，这种方法效果最好，也就是说它没有被挂载并且没有任何进程的 I/O 操作访问它。</p><p>这种备份方法的缺点是镜像将具有和磁盘或分区一样的大小，即使实际数据占用的是一个很小的比例。比如，如果你想要为只使用了10%的20GB的分区创建镜像，那么镜像文件将仍旧是20GB。换句话来讲，它不仅包含了备份的实际数据，而且也包含了整个分区。如果你想完整备份你的设备，那么你可以考虑使用这个方法。</p><p><strong>从现有的设备创建一个镜像文件</strong></p><pre><code># dd if=/dev/sda of=/system_images/sda.img
或者
--------------------- 可选地，你可以压缩镜像文件 -------------------
# dd if=/dev/sda | gzip -c &gt; /system_images/sda.img.gz
</code></pre><p><strong>从镜像文件恢复备份</strong></p><pre><code># dd if=/system_images/sda.img of=/dev/sda
或者
--------------------- 根据你创建镜像文件时的选择(译者注:比如压缩) ----------------
# gzip -dc /system_images/sda.img.gz | dd of=/dev/sda
</code></pre>`,67)),s("p",null,[e[5]||(e[5]=t("方法2：使用 tar 命令备份确定的文件/文件夹——已经在本系列",-1)),n(d,{href:"https://linux.cn/article-7171-1.html"},{default:p(()=>[...e[4]||(e[4]=[t("第三讲",-1)])]),_:1}),e[6]||(e[6]=t("中讲了。如果你想要备份指定的文件/文件夹(配置文件，用户主目录等等)，你可以使用这种方法。",-1))]),e[34]||(e[34]=r(`<p>方法3：使用 rsync 命令同步文件。rsync 是一种多功能远程（和本地）文件复制工具。如果你想要从网络设备备份或同步文件，rsync 是一种选择。</p><p>无论是你是正在同步两个本地文件夹还是本地 &lt; — &gt; 挂载在本地文件系统的远程文件夹，其基本语法是一样的。</p><pre><code># rsync -av source_directory destination_directory
</code></pre><p>在这里，-a 递归遍历子目录(如果它们存在的话)，维持符号链接、时间戳、权限以及原本的属主/属组，-v 显示详细过程。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/rsync-synchronizing-Files.png" alt="rsync Synchronizing Files"></p><p><em>rsync 同步文件</em></p><p>除此之外，如果你想增加在网络上传输数据的安全性，你可以通过 ssh 协议使用 rsync。</p><p><strong>通过 ssh 同步本地到远程文件夹</strong></p><pre><code># rsync -avzhe ssh backups root@remote_host:/remote_directory/
</code></pre><p>这个示例，本地主机上的 backups 文件夹将与远程主机上的 /root/remote_directory 的内容同步。</p><p>在这里，-h 选项以易读的格式显示文件的大小，-e 标志用于表示一个 ssh 连接。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/rsync-synchronize-Remote-Files.png" alt="rsync Synchronize Remote Files"></p><p><em>rsync 同步远程文件</em></p><p><strong>通过ssh同步远程到本地文件夹</strong></p><p>在这种情况下，交换前面示例中的 source 和 destination 文件夹。</p><pre><code># rsync -avzhe ssh root@remote_host:/remote_directory/ backups
</code></pre><p>请注意这些只是 rsync 用法的三个示例而已(你可能遇到的最常见的情形)。对于更多有关 rsync 命令的示例和用法 ，你可以查看下面的文章。</p>`,17)),s("ul",null,[s("li",null,[n(d,{href:"http://www.tecmint.com/rsync-local-remote-file-synchronization-commands/"},{default:p(()=>[...e[7]||(e[7]=[t("在 Linux 下同步文件的10个 rsync命令",-1)])]),_:1})])]),e[35]||(e[35]=s("h3",{id:"总结",tabindex:"-1"},[t("总结 "),s("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),e[36]||(e[36]=s("p",null,"作为一个系统管理员，你需要确保你的系统表现得尽可能好。如果你做好了充分准备，并且如果你的数据完整性能被诸如 RAID 和系统日常备份的存储技术支持，那你将是安全的。",-1)),e[37]||(e[37]=s("p",null,"如果你有有关完善这篇文章的问题、评论或者进一步的想法，可以在下面畅所欲言。除此之外，请考虑通过你的社交网络简介分享这系列文章。",-1)),e[38]||(e[38]=s("hr",null,null,-1)),s("p",null,[e[9]||(e[9]=t("via: ",-1)),n(d,{href:"http://www.tecmint.com/creating-and-managing-raid-backups-in-linux/"},{default:p(()=>[...e[8]||(e[8]=[t("http://www.tecmint.com/creating-and-managing-raid-backups-in-linux/",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=t("作者：",-1)),n(d,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[10]||(e[10]=[t("Gabriel Cánepa",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),n(d,{href:"https://github.com/cposture"},{default:p(()=>[...e[11]||(e[11]=[t("cpsoture",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),n(d,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创翻译，",-1)),n(d,{href:"https://linux.cn/"},{default:p(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const R=i(m,[["render",g]]);export{I as __pageData,R as default};
